using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidResearchQueueFileStore{private readonly string _path;public AndroidResearchQueueFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(IReadOnlyList<AndroidResearchQueueItem> value){ArgumentNullException.ThrowIfNull(value);Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public IReadOnlyList<AndroidResearchQueueItem> Load()=>JsonSerializer.Deserialize<AndroidResearchQueueItem[]>(File.ReadAllText(_path))??throw new InvalidOperationException("Research queue JSON is invalid.");}
